  for(int i=0;i<m*n;i++) c[i]=0;
  // column major gemm: C(m,n) = A(m,k) B(k,n)
  auto e = oneapi::math::blas::column_major::gemm(q, oneapi::math::transpose::nontrans, oneapi::math::transpose::nontrans, m,n,k,1.0f,a,m,b,k,0.0f,c,m,{});
