  auto s=std::chrono::high_resolution_clock::now();
  for(int r=0;r<20;r++){ auto ee=oneapi::math::blas::column_major::gemm(q, oneapi::math::transpose::nontrans, oneapi::math::transpose::nontrans, M,N,K,1.0f,A,M,B,K,0.0f,C,M,{}); ee.wait();}
  auto e2=std::chrono::high_resolution_clock::now();
  std::cout<<"20x gemm ms="<<std::chrono::duration<double,std::milli>(e2-s).count()/20.0<<std::endl;
  sycl::free(a,q);sycl::free(b,q);sycl::free(c,q);sycl::free(A,q);sycl::free(B,q);sycl::free(C,q);
