  // reference:
  bool ok=true;
  for(int i=0;i<M;i++) for(int j=0;j<N;j++){
    float ref=0; for(int k=0;k<K;k++) ref += (float)A[i*K+k]*(float)B[j*K+k];
    float got = C[i*N+j]; // if row-major view correct
    // also col-major view: C[j + i*N]
    float got2 = C[j + i*N];
    if(std::fabs(ref-got)>1e-3){ ok=false; std::cout<<"mismatch i="<<i<<" j="<<j<<" ref="<<ref<<" got(row)="<<got<<" got(col)="<<got2<<std::endl; }
  }
  std::cout<<(ok?"MAP OK":"MAP FAIL")<<std::endl;
  // print C
  for(int i=0;i<M;i++){ for(int j=0;j<N;j++) std::cout<<C[i*N+j]<<" "; std::cout<<std::endl; }
  sycl::free(A,q);sycl::free(B,q);sycl::free(C,q);
  return 0;
}
