#include <sycl/sycl.hpp>
#include <iostream>
#include <vector>
#include <cmath>
#include "oneapi/math/blas.hpp"
static sycl::queue q{sycl::default_selector_v};
using bf16 = sycl::ext::oneapi::bfloat16;
// candidate: dinp(BT,C) = dout(BT,OC) @ W(OC,C).
// Option A: loop oc-tiles? Option B: single gemm(trans W, trans dout) fails in MKL.
// Option C: row-major::gemm? row_major maps to same impl with swapped args - may still fail.
// Option D: transpose inputs on the fly? C=768,BT=256: materialize dout^T (OC x BT) via kernel (5M els, cheap), then gemm(nontrans W? no...
//   dinp^T(C,BT) = W^T(C,OC) @ dout^T(OC,BT): gemm(trans=W? A=W col(C x OC)? ...
//   With explicit BT1 = dout^T stored col-major (OC x BT, lda=OC): gemm(trans, nontrans, m=C,n=BT,k=OC, A=W lda=C, B=BT1 lda=OC): trans/nontrans usually supported.
void transpose_rm(const bf16* src, bf16* dst, int R, int Cc){
  q.parallel_for(sycl::range<1>((size_t)R*Cc), [=](sycl::id<1> i){
    size_t r=i/(size_t)Cc, c=i%(size_t)Cc; dst[c*(size_t)R+r]=src[r*(size_t)Cc+c];
  }).wait();
}
int main(){
  using namespace oneapi::math;
  int64_t BT=256,OC=2304,C=768;
  std::vector<bf16> hW((size_t)OC*C), hD((size_t)BT*OC);
  for(size_t i=0;i<hW.size();i++) hW[i]=bf16(0.01f*((int)(i%13)-6));
  for(size_t i=0;i<hD.size();i++) hD[i]=bf16(0.01f*((int)(i%7)-3));
  bf16* W=sycl::malloc_device<bf16>(hW.size(),q);
  bf16* D=sycl::malloc_device<bf16>(hD.size(),q);
  bf16* DT=sycl::malloc_device<bf16>(hD.size(),q);
  float* Y=sycl::malloc_device<float>((size_t)BT*C,q);
  q.memcpy(W,hW.data(),hW.size()*sizeof(bf16)).wait();
  q.memcpy(D,hD.data(),hD.size()*sizeof(bf16)).wait();
  transpose_rm(D,DT,(int)BT,(int)OC);
  try{
    auto e = blas::column_major::gemm(q, transpose::trans, transpose::nontrans, C,BT,OC,1.0f,W,C,DT,OC,0.0f,Y,C,{});
    e.wait(); std::cout<<"optionD ok"<<std::endl;
  }catch(std::exception& e){ std::cout<<"optionD FAIL: "<<e.what()<<std::endl; return 1; }
  std::vector<float> hY((size_t)BT*C);
  q.memcpy(hY.data(),Y,hY.size()*sizeof(float)).wait();
  double maxd=0;
  for(int t=0;t<10;t++){ int bt=t*37%BT, c=t*7919%C;
    double ref=0; for(int64_t k=0;k<OC;k++) ref += (double)(float)hD[bt*OC+k]*(double)(float)hW[k*C+c];
    double got = hY[c+bt*C]; // col-major (C,BT) -> row [bt,c]
    maxd=std::max(maxd,std::fabs(ref-got));
    if(t<3) std::cout<<"bt="<<bt<<" c="<<c<<" ref="<<ref<<" got="<<got<<std::endl;
  }
  std::cout<<"maxd="<<maxd<<std::endl;
  return 0;
}
