// Batched attention GEMMs via oneMath (one call per head-batch is too slow on
// CPU; we fold B*NH heads into a single larger GEMM over the head dimension by
// looping heads on the host but issuing one oneMath call per (B) batch... in
// practice B*NH is small (<=48) so loop heads with single GEMM each).
// Layouts are row-major (B,NH,T,HS)/(B,NH,T,T); we reuse the sycl_matmul_*
// row-major helpers per head.
inline void att_batched_gemm_qk(floatX* preatt, const floatX* k, const floatX* q,
                                size_t BNH, size_t T, size_t HS, float* tmp) {
    using namespace oneapi::math;
    for (size_t h = 0; h < BNH; h++) {
        const floatX* kh = k + h * T * HS;
        const floatX* qh = q + h * T * HS;
        float* ch = tmp + h * T * T;
        // C_row(T,T) = A_row(T,HS) @ B_row^T(HS,T): col C^T(T,T) = B(T,HS) @ A^T(HS,T)
        // gemm(trans=qh, nontrans=kh, m=T,n=T,k=HS, lda=HS, ldb=HS, ldc=T)
        auto e = blas::column_major::gemm(sycl_queue, transpose::trans, transpose::nontrans,
            (int64_t)T, (int64_t)T, (int64_t)HS, 1.0f, qh, (int64_t)HS, kh, (int64_t)HS,
